with filtered as (select id, customer_id, device, browser, started_at, country, trim(device) as clean_device from sessions where country is not null and started_at < '2024-11-19'), with_gaps as (select *, case when started_at - lag(started_at) over (partition by browser order by started_at, id) > interval 7 days then 1 else 0 end as is_new_session from filtered), islands as (select *, sum(is_new_session) over (partition by browser order by started_at, id rows between unbounded preceding and current row) as burst_id from with_gaps) select case when burst_id >= 7 then 'HIGH' else 'LOW' end as burst_id_tier, date_trunc('week', started_at) as week_start, round(avg(burst_id), 2) as avg_burst_id, (unix_timestamp(max(started_at)) - unix_timestamp(min(started_at))) / 60 as span_minutes, approx_percentile(is_new_session, array(0.25, 0.5, 0.75)) as is_new_session_quartiles from islands group by 1, 2 having avg_burst_id > 0;
